use std::{fs,path::PathBuf,sync::Arc};
use photocraft_doc::*;
use photocraft_geom::{Affine,Rect};
use photocraft_format::{save_to_bytes,SaveOptions};
use photocraft_raster::Surface;
use photocraft_algo::{FilterParams,UndefinedAreas,Image};
use serde_json::json;
fn words(s:&Surface,w:i32,h:i32)->Vec<u8>{let mut out=Vec::new();for y in 0..h{for x in 0..w{let mut p=[0.0f32;4];s.read_pixel(x,y,&mut p);for v in p{out.extend_from_slice(&v.to_bits().to_le_bytes())}}}out}
fn main(){let out=PathBuf::from(std::env::args().nth(1).unwrap());fs::create_dir_all(&out).unwrap();let mut rows=Vec::new();
for(bits,depth)in[("u8",SampleType::U8),("u16",SampleType::U16),("f32",SampleType::F32)]{for name in ["default","path","document-name","document-index","mono-neutral","stretch","tile-repeat","tile-wrap","transparent-edges","fractional","negative","hdr-map","transparent-input","translated","tile-boundary"]{
if name=="tile-boundary" && bits!="f32"{continue}let(w,h)=if name=="tile-boundary"{(257,129)}else{(23,19)};let(mw,mh)=(7,5);let mono=name=="mono-neutral";let channels=if mono{1}else{2};let horizontal=if name=="fractional"{12.75}else if name=="negative"{-37.0}else{25.0};let vertical=if name=="fractional"{-8.125}else{15.0};let stretch=!["tile-repeat","tile-wrap"].contains(&name);let edge=if name=="tile-wrap"{UndefinedAreas::Wrap}else if name=="transparent-edges"{UndefinedAreas::Transparent}else{UndefinedAreas::Repeat};
let mut pixels=Surface::new(PixelFormat{mode:ColorMode::Rgb,sample:depth,alpha:true});for y in 0..h{for x in 0..w{let alpha=if name=="transparent-input" &&(x+y)%4==0{0.0}else if(x+y)%5==0{0.4}else{1.0};let k=if bits=="f32"{2.5}else{1.0};pixels.write_pixel(x,y,&[(0.05+x as f32/w as f32*0.7)*k,(0.1+y as f32/h as f32*0.6)*k,(0.08+((x+y)%9)as f32/12.0)*k,alpha])}}
let mut map=Image::new(Rect::new(0,0,mw,mh),4);let mut map_data=Vec::new();let mut map_surface=Surface::new(PixelFormat{mode:ColorMode::Rgb,sample:SampleType::F32,alpha:true});for y in 0..mh{for x in 0..mw{let(r,g,b)=if mono{(0.5,0.5,0.5)}else if name=="hdr-map"{(-0.75+x as f32/2.0,1.5-y as f32/2.0,0.42)}else{(0.15+x as f32/(mw-1)as f32*0.7,0.25+y as f32/(mh-1)as f32*0.5,0.42)};let i=((y*mw+x)*4)as usize;map.data[i..i+4].copy_from_slice(&[r,g,b,1.0]);map_surface.write_pixel(x,y,&[r,g,b,1.0]);map_data.extend_from_slice(&r.to_bits().to_le_bytes());if !mono{map_data.extend_from_slice(&g.to_bits().to_le_bytes())}}}
let mut original=Document::new(format!("Owned Displacement {name}"),Size::new(w as u32,h as u32),ColorMode::Rgb,depth);original.layers.clear();original.layers.push(Layer::new("Owned source pixels",LayerContent::Raster(pixels.clone())));let bytes=save_to_bytes(&original,&SaveOptions::default()).unwrap();let base=format!("{name}-{bits}");let source_file=format!("{base}-source.pcraft");fs::write(out.join(&source_file),&bytes).unwrap();let input=format!("{base}-input.rgba32");fs::write(out.join(&input),words(&pixels,w,h)).unwrap();let map_file=format!("{base}-map.float32");fs::write(out.join(&map_file),map_data).unwrap();
let mut params=json!({"horizontal":horizontal,"vertical":vertical,"fit":if stretch{"stretch"}else{"tile"},"undefinedAreas":match edge{UndefinedAreas::Wrap=>"wrap",UndefinedAreas::Transparent=>"transparent",_=>"repeat"}});if name=="path" || name=="stretch"{params["mapPath"]=json!("Owned missing map.psd")}if name=="document-name"{params["mapDocument"]=json!("Owned map document");params["mapLayer"]=json!(17)}if name=="document-index"{params["mapDocument"]=json!(1);params["mapLayer"]=json!(19)}
let placement=if name=="translated"{Affine::translate(3.0,2.0)}else{Affine::IDENTITY};let mut smart=SmartObject::new(SmartSource::Embedded{file_name:"Owned Displacement source.pcraft".into(),bytes:Arc::new(bytes)},placement,None);let placed=photocraft_engine::smart_cmds::render(&original,&smart).unwrap().unwrap();smart.smart_filters.push(SmartFilter{command:"filter.distort.displace".into(),params:params.clone(),blend:BlendMode::Normal,opacity:1.0,visible:true});let unresolved=photocraft_engine::smart_cmds::render(&original,&smart).unwrap().unwrap();let spec=FilterParams::Displace{horizontal,vertical,stretch,undefined:edge,map:Some(Arc::new(map))};let bounds=original.bounds();let area=photocraft_algo::output_area(&spec,placed.content_bounds(),bounds,None);let bound=photocraft_algo::apply_in(&placed,&spec,area,bounds,None,bounds.union(&placed.content_bounds()));let un_file=format!("{base}-unresolved.rgba32");let bound_file=format!("{base}-bound.rgba32");fs::write(out.join(&un_file),words(&unresolved,w,h)).unwrap();fs::write(out.join(&bound_file),words(&bound,w,h)).unwrap();let cached_bound=!["default","path","document-name","document-index"].contains(&name);let mut project=original.clone();smart.cache=Some(if cached_bound{bound}else{unresolved});project.layers=vec![Layer::new("Owned editable Displace",LayerContent::Smart(smart.clone()))];let cached=format!("{base}-cached.pcraft");fs::write(out.join(&cached),save_to_bytes(&project,&SaveOptions::default()).unwrap()).unwrap();smart.cache=None;project.layers=vec![Layer::new("Owned editable Displace",LayerContent::Smart(smart))];let uncached=format!("{base}-uncached.pcraft");fs::write(out.join(&uncached),save_to_bytes(&project,&SaveOptions::default()).unwrap()).unwrap();
let mut map_doc=Document::new("Owned float map",Size::new(mw as u32,mh as u32),ColorMode::Rgb,SampleType::F32);map_doc.layers.clear();map_doc.layers.push(Layer::new("Numerical map channels",LayerContent::Raster(map_surface)));let map_project=format!("{base}-map.pcraft");fs::write(out.join(&map_project),save_to_bytes(&map_doc,&SaveOptions::default()).unwrap()).unwrap();
rows.push(json!({"name":name,"depth":bits,"width":w,"height":h,"horizontal":horizontal,"vertical":vertical,"fit":if stretch{"stretchToFit"}else{"tile"},"edge":match edge{UndefinedAreas::Wrap=>"wrapAround",UndefinedAreas::Transparent=>"transparent",_=>"repeatEdge"},"sourceParams":params,"mapWidth":mw,"mapHeight":mh,"mapChannels":channels,"mapSamples":map_file,"mapProject":map_project,"cachedBound":cached_bound,"source":source_file,"input":input,"unresolvedExpected":un_file,"boundExpected":bound_file,"cached":cached,"uncached":uncached}));
}}
fs::write(out.join("cases.json"),serde_json::to_vec_pretty(&rows).unwrap()).unwrap();println!("{} original displacement vectors",rows.len());}
